import{_ as e,o as t,c as a,a3 as o}from"./chunks/framework.qCVWde4n.js";const b=JSON.parse('{"title":"框架源码结构","description":"","frontmatter":{},"headers":[],"relativePath":"dev/codebase.md","filePath":"dev/codebase.md","lastUpdated":null}'),s={name:"dev/codebase.md"};function c(n,d,r,l,i,p){return t(),a("div",null,[...d[0]||(d[0]=[o(`<h1 id="框架源码结构" tabindex="-1">框架源码结构 <a class="header-anchor" href="#框架源码结构" aria-label="Permalink to &quot;框架源码结构&quot;">​</a></h1><p>整个框架是在<strong>反编译还原的游戏源码</strong>之上，新增的 15 个 <code>Mod*.cs</code> 文件 + 少量挂钩修改。这一页带你认路。</p><h2 id="顶层目录" tabindex="-1">顶层目录 <a class="header-anchor" href="#顶层目录" aria-label="Permalink to &quot;顶层目录&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>p1/</span></span>
<span class="line"><span>├── src/                 ← 全部 C# 源码（游戏还原 + 框架）</span></span>
<span class="line"><span>├── build/               ← 一键构建流水线（Python）</span></span>
<span class="line"><span>├── tools/               ← Mod 仓库发布工具</span></span>
<span class="line"><span>├── docs-site/           ← 本文档站（VitePress）</span></span>
<span class="line"><span>├── mods-example/        ← 示例 Mod，可复制着改</span></span>
<span class="line"><span>├── refs/                ← 参考资料</span></span>
<span class="line"><span>├── README.md            ← 功能总说明（给人看的）</span></span>
<span class="line"><span>├── MODDING_GUIDE.md     ← Mod 写法（给作者看的）</span></span>
<span class="line"><span>├── TECHNICAL.md         ← 技术细节</span></span>
<span class="line"><span>├── CHANGELOG.md         ← 版本演进与踩坑史</span></span>
<span class="line"><span>├── ROADMAP.md           ← 未实现项的设计存档</span></span>
<span class="line"><span>└── REPO.md              ← Mod 仓库运维</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br></div></div><h2 id="框架的-15-个文件各干什么" tabindex="-1">框架的 15 个文件各干什么 <a class="header-anchor" href="#框架的-15-个文件各干什么" aria-label="Permalink to &quot;框架的 15 个文件各干什么&quot;">​</a></h2><p>按「加载链 → 数据 → 界面 → 周边」分组：</p><h3 id="加载与配置-核心" tabindex="-1">加载与配置（核心） <a class="header-anchor" href="#加载与配置-核心" aria-label="Permalink to &quot;加载与配置（核心）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>文件</th><th>职责</th></tr></thead><tbody><tr><td><code>ModBridge.cs</code></td><td><strong>总入口</strong>。<code>Init()</code> 按顺序启动配置、档案、加载器；是理解整个初始化流程的起点</td></tr><tr><td><code>ModLoader.cs</code></td><td>扫描 <code>mods/</code> 目录、解析每个 <code>mod.json</code>、处理禁用/删除/日志尾部、冲突检测</td></tr><tr><td><code>ModConfig.cs</code></td><td>参数系统。23 个 <code>ParamDef</code> 定义、有效值表、覆盖层、<code>AFMOD_settings.json</code> 读写</td></tr><tr><td><code>MiniJson</code>（内嵌）</td><td>极简 JSON 解析器，避免外部依赖</td></tr></tbody></table><h3 id="数据定义" tabindex="-1">数据定义 <a class="header-anchor" href="#数据定义" aria-label="Permalink to &quot;数据定义&quot;">​</a></h3><table tabindex="0"><thead><tr><th>文件</th><th>职责</th></tr></thead><tbody><tr><td><code>ModShipDef.cs</code></td><td>一艘舰船的字段定义（<code>class</code> / <code>type</code> / <code>nation</code> / 装甲 / 主炮 …）</td></tr><tr><td><code>ModShips.cs</code></td><td>把 <code>ships[]</code> 注入游戏 <code>DatabaseShipData</code> 数组</td></tr><tr><td><code>ModFleetDef.cs</code></td><td>一支编队的字段定义（<code>fleetName</code> / <code>ships[]</code> / <code>date</code> …）</td></tr><tr><td><code>ModFleets.cs</code></td><td>把 <code>fleets[]</code> 注入「自定义战斗」任务项</td></tr><tr><td><code>ModModels.cs</code></td><td>模型通道。扫 <code>models/</code>、<code>AssetBundle.CreateFromFile</code>、三档兜底</td></tr></tbody></table><h3 id="运行时与界面" tabindex="-1">运行时与界面 <a class="header-anchor" href="#运行时与界面" aria-label="Permalink to &quot;运行时与界面&quot;">​</a></h3><table tabindex="0"><thead><tr><th>文件</th><th>职责</th></tr></thead><tbody><tr><td><code>ModRuntime.cs</code></td><td>运行时驱动。找 <code>Database</code>、执行 <code>unlock.allShips</code> 解锁等一次性注入</td></tr><tr><td><code>ModPanel.cs</code></td><td><strong>游戏内控制台「小u」</strong>。6 个标签页的全部界面（OnGUI 即时模式）</td></tr><tr><td><code>ModProbe.cs</code></td><td>「状态」页探针。每 0.5 秒读战斗现场（回合 / 装填 / 倍速…）</td></tr><tr><td><code>ModSaveEdit.cs</code></td><td>「存档」页。改运行时 <code>currentRenown</code> / <code>campaignTurn</code>，走游戏自带 <code>Save()</code></td></tr></tbody></table><h3 id="账号与分享" tabindex="-1">账号与分享 <a class="header-anchor" href="#账号与分享" aria-label="Permalink to &quot;账号与分享&quot;">​</a></h3><table tabindex="0"><thead><tr><th>文件</th><th>职责</th></tr></thead><tbody><tr><td><code>ModProfile.cs</code></td><td>玩家本地档案 <code>AFMOD_profile.json</code>（代号 / 威望 / 战绩）</td></tr><tr><td><code>ModShareCode.cs</code></td><td>分享码编解码（<code>AFMOD1:</code> + Base64），<code>_sharein/</code> 导入</td></tr><tr><td><code>ModLogHook.cs</code></td><td>引擎异常桥接。把 Unity 的 Error/Exception/Assert 自动抓进日志页</td></tr></tbody></table><h2 id="被改动的游戏源码-挂钩点" tabindex="-1">被改动的游戏源码（挂钩点） <a class="header-anchor" href="#被改动的游戏源码-挂钩点" aria-label="Permalink to &quot;被改动的游戏源码（挂钩点）&quot;">​</a></h2><p>框架不是靠运行时织入，而是<strong>重编译整个 <code>Assembly-CSharp.dll</code></strong>：在反编译出的游戏源码里直接改调用点。主要挂钩：</p><table tabindex="0"><thead><tr><th>游戏文件</th><th>改了什么</th></tr></thead><tbody><tr><td><code>LevelLoadManager.cs</code></td><td>12 处 <code>Resources.Load(&quot;ships/…&quot;)</code> → <code>ModModels.LoadShipModel(…)</code></td></tr><tr><td><code>Compartment.cs</code></td><td>伤害计算点按武器类型乘倍率（鱼雷/主炮/航弹/深弹/刺猬）</td></tr><tr><td><code>DynamicCampaign.cs</code></td><td>威望结算、新战役起始威望、修理时间</td></tr><tr><td><code>UIFunctions.cs</code></td><td>航母出击架数、AI 反应计时、威望发放、自定义舰船注入</td></tr><tr><td><code>CombatAI.cs</code></td><td>AI 反应速度、出击架数</td></tr><tr><td><code>ShipData.cs</code></td><td>探测距离（<code>visualRange</code>）</td></tr><tr><td><code>Projectile.cs</code></td><td>鱼雷转向步长</td></tr><tr><td><code>Database.cs</code></td><td>舰级可用性数组（<code>unlock.allShips</code>）</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">编译通过 = 挂钩绑定成功</p><p>如果挂钩的方法名写错，C# 编译器会直接报 <code>CS0103</code> / <code>CS0117</code>。所以「编译通过」本身就是挂钩生效的铁证，不需要额外验证。</p></div><h2 id="构建流水线" tabindex="-1">构建流水线 <a class="header-anchor" href="#构建流水线" aria-label="Permalink to &quot;构建流水线&quot;">​</a></h2><p><code>build/</code> 目录下的 Python 脚本：</p><table tabindex="0"><thead><tr><th>脚本</th><th>作用</th></tr></thead><tbody><tr><td><code>run_all.py</code></td><td><strong>一键全流程</strong>：编译 → 汉化补丁 → 打包 → 签名</td></tr><tr><td><code>compile.py</code></td><td>用 Mono / .NET 编译 <code>Assembly-CSharp.csproj</code> → DLL</td></tr><tr><td><code>patch_localization.py</code></td><td>汉化补丁（对 <code>#US</code> 堆做原地等长替换）</td></tr><tr><td><code>build_apk.py</code></td><td>组装并打包 APK</td></tr><tr><td><code>fix_ilspy_defects.py</code></td><td>修反编译缺陷（逐行号精确修 <code>yield break</code>）</td></tr></tbody></table><h2 id="一个必须记住的约束" tabindex="-1">一个必须记住的约束 <a class="header-anchor" href="#一个必须记住的约束" aria-label="Permalink to &quot;一个必须记住的约束&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">目标运行时是 Unity 4.7 / Mono / .NET 3.5</p><p>新增代码必须用 <strong>C# 3.0</strong> 语法。用高版本语法会编译失败。具体禁用清单见 <a href="/AtlanticFleetSite/docs/dev/cs30-limits">C# 3.0 兼容约束</a>。</p></div><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>从零搭环境 → <a href="/AtlanticFleetSite/docs/dev/build-env">编译环境搭建</a></li><li>想改代码 → <a href="/AtlanticFleetSite/docs/dev/cs30-limits">C# 3.0 兼容约束</a> → <a href="/AtlanticFleetSite/docs/dev/hack">如何修改框架本身</a></li><li>调试手段 → <a href="/AtlanticFleetSite/docs/dev/logging-api">调试与日志接口</a></li></ul>`,25)])])}const u=e(s,[["render",c]]);export{b as __pageData,u as default};
